<?php
namespace App\Http\Resources;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;
class EmployeeResource extends JsonResource { public function toArray(Request $request): array { $doors=$this->relationLoaded('doors')?$this->doors:$this->doors()->get(); return ['id'=>$this->id,'user_id'=>$this->employee_id,'employee_id'=>$this->employee_id,'hikvision_employee_no'=>$this->hikvision_employee_no ?: $this->employee_id,'nik'=>$this->nik,'name'=>$this->name,'email'=>$this->email,'phone'=>$this->phone,'photo_path'=>$this->photo_path,'card_no'=>$this->card_no,'card_no_masked'=>$this->card_no ? str_repeat('*',max(strlen($this->card_no)-4,0)).substr($this->card_no,-4) : null,'department'=>$this->department,'role'=>$this->role,'role_jabatan'=>$this->role_jabatan,'employment_type'=>$this->employment_type,'employment_status'=>$this->employment_status,'hire_date'=>$this->hire_date?->toDateString(),'building'=>$this->building?->only(['id','code','name']),'division'=>$this->division?->only(['id','code','name']),'position'=>$this->position?->only(['id','code','name']),'supervisor'=>$this->supervisor?->only(['id','employee_id','name']),'biometric_status'=>['fingerprint_enrolled'=>(bool)optional($this->biometricStatus)->has_fingerprint,'card_enrolled'=>(bool)optional($this->biometricStatus)->card_enrolled],'door_assign'=>$doors->map(fn($door)=>['door_id'=>$door->door_id,'door_name'=>($door->name??$door->door_name)." ({$door->location})",'sync_status'=>$door->pivot->sync_status??'pending','last_sync_error'=>$door->pivot->last_sync_error??null]),'created_at'=>$this->created_at?->toIso8601String()]; } }
